function Assert-True([bool]$Condition,[string]$Message){if(-not $Condition){throw "TEST FEHLGESCHLAGEN: $Message"};$script:Passed++}
function Assert-Throws([scriptblock]$Action,[string]$Message){$ok=$false;try{&$Action|Out-Null}catch{$ok=$true};Assert-True $ok $Message}
function InvokeFixtureGit([string]$Repo,[string[]]$GitArgs){$env:GIT_OPTIONAL_LOCKS='0';$old=$ErrorActionPreference;try{$ErrorActionPreference='Continue';$out=@(& git.exe -c core.autocrlf=false -C $Repo @GitArgs 2>&1);if($LASTEXITCODE-ne 0){throw ($out-join"`n")};($out-join"`n").Trim()}finally{$ErrorActionPreference=$old}}
function WriteUtf8([string]$Path,[string]$Text){$dir=Split-Path -Parent $Path;if($dir){[IO.Directory]::CreateDirectory($dir)|Out-Null};[IO.File]::WriteAllText($Path,$Text,[Text.UTF8Encoding]::new($false))}
function Sha([byte[]]$Bytes){Get-UniversaarlBytesSha256 $Bytes}
try{
 [IO.Directory]::CreateDirectory($Temp)|Out-Null
