 WriteUtf8 (Join-Path $blue $indexPath) ($indexHeader+"  - { id: UABC-FIXTURE-PLAN-001, kindId: project-plan, path: $payloadPath, format: yaml, required: true }`n  - { id: UABC-FIXTURE-PLAN-001, kindId: simulation, path: $phase2, format: yaml, required: true }`n  - { id: UABC-FIXTURE-PHASE3-001, kindId: simulation, path: $phase3, format: yaml, required: true }`n");InvokeFixtureGit $blue @('add',$indexPath)|Out-Null;InvokeFixtureGit $blue @('commit','--quiet','-m','duplicate id')|Out-Null;$badCommit=InvokeFixtureGit $blue @('rev-parse','HEAD');Assert-Throws {Test-UniversaarlBranchIndex $blue $badCommit 'codex/universaarl-projekt'} 'Doppelte Index-ID wurde akzeptiert.'
 WriteUtf8 (Join-Path $blue $indexPath) ($indexHeader+"  - { id: UABC-FIXTURE-PLAN-001, kindId: project-plan, path: $payloadPath, format: yaml, required: true }`n  - { id: UABC-FIXTURE-PHASE3-001, kindId: simulation, path: $phase3, format: yaml, required: true }`n");InvokeFixtureGit $blue @('add',$indexPath)|Out-Null;InvokeFixtureGit $blue @('commit','--quiet','-m','missing phase')|Out-Null;$badCommit=InvokeFixtureGit $blue @('rev-parse','HEAD');Assert-Throws {Test-UniversaarlBranchIndex $blue $badCommit 'codex/universaarl-projekt'} 'Fehlende aktuelle Simulationsevidence wurde akzeptiert.'
